<template><section class="orders"><div class="heading"><div><h1>My orders</h1><p>Track your recent purchases.</p></div><router-link class="btn" to="/products">Continue shopping</router-link></div><div v-if="loading">Loading orders...</div><div v-else-if="!orders.length" class="empty">No orders yet.</div><article v-for="order in orders" :key="order.id" class="order"><div><strong>#{{ order.id.slice(0,8) }}</strong><span>{{ new Date(order.createdAt).toLocaleString() }}</span></div><div><b>Rs.{{ order.total }}</b><span class="status">{{ order.status }}</span></div><p>{{ order.items.map(i => `${i.productName} × ${i.quantity}`).join(', ') }}</p></article></section></template>
<script>
import axios from 'axios'; import { useAuthStore } from '../stores/authStore.js'; export default { data:()=>({ orders:[],loading:true }), async created(){ try{this.orders=(await axios.get(`http://localhost:8083/api/orders/user/${useAuthStore().user.id}`)).data} finally{this.loading=false} } }
</script>
<style scoped>.orders{max-width:850px;margin:auto}.heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.heading p{color:#666}.btn{background:#4a00e0;color:#fff;padding:10px 15px;border-radius:7px;text-decoration:none}.order{background:#fff;margin:12px 0;padding:18px;border-radius:10px;box-shadow:0 3px 12px #1828480b}.order>div{display:flex;justify-content:space-between;gap:15px}.order span{color:#666;margin-left:15px;font-size:.9rem}.order p{color:#666;margin-top:13px}.status{background:#e9edff;color:#4a00e0!important;padding:4px 8px;border-radius:10px}.empty{text-align:center;padding:50px;color:#666}</style>
